// Count from 1 to 5
for (int i = 1; i <= 5; i++)
{
    Console.WriteLine(i);
}

// Create a pattern
for (int i = 0; i < 5; i++)
{
    for (int j = 0; j <= i; j++)
    {
        Console.Write("*");
    }
    Console.WriteLine();
}

// Countdown from 10 to 1
for (int i = 10; i >= 1; i--)
{
    Console.WriteLine(i);
}
